    CONSTRAINT fk_products_brand_id FOREIGN KEY (brand_id) REFERENCES northwind.brands (id) ON DELETE SET NULL,
    CONSTRAINT fk_products_category_id FOREIGN KEY (category_id) REFERENCES northwind.product_categories (id) ON DELETE RESTRICT,
    CONSTRAINT fk_products_hazard_class_id FOREIGN KEY (hazard_class_id) REFERENCES northwind.hazard_classes (id) ON DELETE SET NULL,
    CONSTRAINT fk_products_manufacturer_id FOREIGN KEY (manufacturer_id) REFERENCES northwind.manufacturers (id) ON DELETE SET NULL,
    CONSTRAINT fk_products_preferred_supplier_id FOREIGN KEY (preferred_supplier_id) REFERENCES northwind.parties (id) ON DELETE SET NULL,
    CONSTRAINT fk_products_sales_unit_code FOREIGN KEY (sales_unit_code) REFERENCES northwind.units_of_measure (code) ON DELETE SET NULL,
    CONSTRAINT fk_products_storage_condition_id FOREIGN KEY (storage_condition_id) REFERENCES northwind.storage_conditions (id) ON DELETE SET NULL,
    CONSTRAINT fk_products_tariff_code_id FOREIGN KEY (tariff_code_id) REFERENCES northwind.tariff_codes (id) ON DELETE SET NULL,
    CONSTRAINT ck_products_discontinued_after_launch CHECK (discontinued_on IS NULL OR launched_on IS NULL OR discontinued_on >= launched_on)
);
CREATE INDEX ix_products_status_name ON northwind.products (status, name);
CREATE INDEX ix_products_name ON northwind.products (name);
COMMENT ON COLUMN northwind.products.name IS 'Searched with a trigram index in production.';

-- northwind.customer_price_agreements
CREATE TABLE northwind.customer_price_agreements (
