    id uuid NOT NULL,
    level smallint NOT NULL,
    issued_on date NOT NULL,
    amount_overdue_amount numeric(19,4) NOT NULL,
    amount_overdue_currency varchar(3) NOT NULL,
    fee_amount_amount numeric(19,4) NULL,
    fee_amount_currency varchar(3) NULL,
    sent_via varchar(20) NULL,
    collection_case_id uuid NULL,
    invoice_id uuid NOT NULL,
