    CONSTRAINT fk_freight_rates_shipping_zone_id FOREIGN KEY (shipping_zone_id) REFERENCES northwind.shipping_zones (id) ON DELETE RESTRICT
);

-- northwind.goods_receipts
CREATE TABLE northwind.goods_receipts (
