    updated_by varchar(64) NULL,
    advance_ship_notice_id uuid NULL,
    dock_door_id uuid NULL,
    purchase_order_id uuid NULL,
    received_by_id uuid NULL,
    warehouse_id uuid NOT NULL,
    CONSTRAINT pk_goods_receipts PRIMARY KEY (id),
    CONSTRAINT uq_goods_receipts_receipt_number UNIQUE (receipt_number),
    CONSTRAINT fk_goods_receipts_advance_ship_notice_id FOREIGN KEY (advance_ship_notice_id) REFERENCES northwind.advance_ship_notices (id) ON DELETE SET NULL,
    CONSTRAINT fk_goods_receipts_dock_door_id FOREIGN KEY (dock_door_id) REFERENCES northwind.dock_doors (id) ON DELETE SET NULL,
    CONSTRAINT fk_goods_receipts_purchase_order_id FOREIGN KEY (purchase_order_id) REFERENCES northwind.purchase_orders (id) ON DELETE SET NULL,
    CONSTRAINT fk_goods_receipts_received_by_id FOREIGN KEY (received_by_id) REFERENCES northwind.employees (id) ON DELETE SET NULL,
    CONSTRAINT fk_goods_receipts_warehouse_id FOREIGN KEY (warehouse_id) REFERENCES northwind.warehouses (id) ON DELETE RESTRICT
);

-- northwind.goods_receipt_lines
CREATE TABLE northwind.goods_receipt_lines (
    id uuid NOT NULL,
    quantity_received numeric(12,3) NOT NULL,
    quantity_rejected numeric(12,3) NOT NULL DEFAULT 0,
    rejection_reason varchar(200) NULL,
    bin_id uuid NULL,
    lot_id uuid NULL,
    product_id uuid NOT NULL,
    purchase_order_line_id uuid NULL,
    goods_receipt_id uuid NOT NULL,
    CONSTRAINT pk_goods_receipt_lines PRIMARY KEY (id),
    CONSTRAINT fk_goods_receipt_lines_bin_id FOREIGN KEY (bin_id) REFERENCES northwind.bin_locations (id) ON DELETE SET NULL,
    CONSTRAINT fk_goods_receipt_lines_lot_id FOREIGN KEY (lot_id) REFERENCES northwind.stock_lots (id) ON DELETE SET NULL,
    CONSTRAINT fk_goods_receipt_lines_product_id FOREIGN KEY (product_id) REFERENCES northwind.products (id) ON DELETE RESTRICT,
    CONSTRAINT fk_goods_receipt_lines_purchase_order_line_id FOREIGN KEY (purchase_order_line_id) REFERENCES northwind.purchase_order_lines (id) ON DELETE SET NULL,
    CONSTRAINT fk_goods_receipt_lines_goods_receipt_id FOREIGN KEY (goods_receipt_id) REFERENCES northwind.goods_receipts (id) ON DELETE CASCADE
);

-- northwind.hold_reasons
CREATE TABLE northwind.hold_reasons (
    id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    requires_credit_approval boolean NOT NULL DEFAULT false,
    code varchar(32) NOT NULL,
    name varchar(100) NOT NULL,
    sort_order integer NOT NULL DEFAULT 0,
    is_active boolean NOT NULL DEFAULT true,
    CONSTRAINT pk_hold_reasons PRIMARY KEY (id),
    CONSTRAINT uq_hold_reasons_code UNIQUE (code)
);

-- northwind.integration_outbox
CREATE TABLE northwind.integration_outbox (
    id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    aggregate_type varchar(100) NOT NULL,
    aggregate_id varchar(64) NOT NULL,
    event_type varchar(100) NOT NULL,
    payload jsonb NOT NULL,
    occurred_at timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    relayed_at timestamptz(6) NULL,
    attempts integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_integration_outbox PRIMARY KEY (id)
);
CREATE INDEX ix_integration_outbox_pending ON northwind.integration_outbox (occurred_at) WHERE relayed_at IS NULL;
COMMENT ON TABLE northwind.integration_outbox IS 'Written by the application, drained by the outbox relay.';
COMMENT ON COLUMN northwind.integration_outbox.id IS 'Relay order.';
COMMENT ON COLUMN northwind.integration_outbox.aggregate_type IS 'Entity name of the aggregate that changed.';
COMMENT ON COLUMN northwind.integration_outbox.aggregate_id IS 'Key of the aggregate that changed.';
COMMENT ON COLUMN northwind.integration_outbox.event_type IS 'Event name, such as SalesOrderSubmitted.';
COMMENT ON COLUMN northwind.integration_outbox.payload IS 'Event body.';
COMMENT ON COLUMN northwind.integration_outbox.occurred_at IS 'When the change was committed.';
COMMENT ON COLUMN northwind.integration_outbox.relayed_at IS 'When the relay published the event; null while pending.';
COMMENT ON COLUMN northwind.integration_outbox.attempts IS 'Publish attempts so far.';

-- northwind.inventory_cost_layers
CREATE TABLE northwind.inventory_cost_layers (
    id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
